import { cookies } from 'next/headers';
import { NextResponse } from 'next/server';

/**
 * Bearilly reverse-proxy route — generated by Buildgram.
 *
 * All browser code calls /api/v1/... on the same origin with  credentials: 'same-origin'.
 * This catch-all route forwards allowlisted requests to Bearilly, attaching the
 * short-lived session from an HttpOnly cookie.
 *
 * BEARILLY_URL must be set in .env.local (added by Buildgram).
 */

const BEARILLY_URL = process.env.BEARILLY_URL || '';

function isAllowed(pathname) {
  return pathname.startsWith('/api/v1/') &&
    !pathname.startsWith('/api/v1/billing/') && pathname !== '/api/v1/billing' &&
    !pathname.startsWith('/api/v1/integration/');
}

async function proxyRequest(request, params) {
  const segments = (await params).path || [];
  if (!Array.isArray(segments) || segments.some((segment) => typeof segment !== 'string' || !segment || segment === '.' || segment === '..' || segment.includes('/') || segment.includes(String.fromCharCode(92)))) return NextResponse.json({ error: 'Not found' }, { status: 404 });
  const pathname = '/api/v1/' + segments.join('/');
  if (!isAllowed(pathname)) return NextResponse.json({ error: 'Not found' }, { status: 404 });
  if (!BEARILLY_URL) {
    console.error('[bearilly-proxy] BEARILLY_URL env var is not set.');
    return NextResponse.json({ error: 'Server configuration error' }, { status: 500 });
  }
  const url = new URL(pathname, BEARILLY_URL);
  for (const [key, value] of request.nextUrl.searchParams) url.searchParams.set(key, value);
  const publicTenant = request.method === 'GET' && pathname === '/api/v1/tenant';
  const publicRegistration = request.method === 'POST' && pathname === '/api/v1/auth/register';
  const cookieStore = await cookies();
  const sessionToken = cookieStore.get('bearilly_session')?.value;
  const schoolId = cookieStore.get('bearilly_school_id')?.value;
  const headers = new Headers();
  headers.set('Accept', 'application/json');
  if (publicTenant) {
    headers.set('x-bearilly-host', request.nextUrl.hostname);
  } else if (publicRegistration) {
    const schoolHost = request.nextUrl.hostname;
    const tenantUrl = new URL('/api/v1/tenant', BEARILLY_URL);
    tenantUrl.searchParams.set('host', schoolHost);
    const tenantResponse = await fetch(tenantUrl, {
      headers: { Accept: 'application/json', 'x-bearilly-host': schoolHost },
      cache: 'no-store',
    });
    const tenantPayload = await tenantResponse.json().catch(() => null);
    const originSchoolId = tenantPayload?.data?.school?.id;
    if (!tenantResponse.ok || !originSchoolId) {
      return NextResponse.json({ error: 'This website is not verified for student registration' }, { status: 403 });
    }
    headers.set('x-bearilly-origin-school', originSchoolId);
  } else {
    if (!sessionToken || !schoolId) return NextResponse.json({ error: 'Sign in with your school account first' }, { status: 401 });
    headers.set('x-bearilly-session', sessionToken);
    headers.set('x-bearilly-origin-school', schoolId);
  }
  const ct = request.headers.get('content-type');
  if (ct) headers.set('content-type', ct);
  const init = {
    method: request.method,
    headers,
    ...(request.method !== 'GET' && request.method !== 'HEAD'
      ? { body: await request.arrayBuffer() } : {}),
  };
  const upstream = await fetch(url, init);
  const body = await upstream.arrayBuffer();
  return new NextResponse(body, {
    status: upstream.status,
    headers: { 'content-type': upstream.headers.get('content-type') || 'application/json' },
  });
}

export const GET    = (req, ctx) => proxyRequest(req, ctx.params);
export const POST   = (req, ctx) => proxyRequest(req, ctx.params);
export const PUT    = (req, ctx) => proxyRequest(req, ctx.params);
export const PATCH  = (req, ctx) => proxyRequest(req, ctx.params);
export const DELETE = (req, ctx) => proxyRequest(req, ctx.params);
